import{_ as a,o as t,c as i,ae as r}from"./chunks/framework.CK6jtcgr.js";const u=JSON.parse('{"title":"Entity Analytics Overview","description":"","frontmatter":{},"headers":[],"relativePath":"guide/entity-analytics-overview.md","filePath":"guide/entity-analytics-overview.md"}'),n={name:"guide/entity-analytics-overview.md"};function l(o,e,s,d,c,h){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="entity-analytics-overview" tabindex="-1">Entity Analytics Overview <a class="header-anchor" href="#entity-analytics-overview" aria-label="Permalink to &quot;Entity Analytics Overview&quot;">​</a></h1><p>Entity Analytics is the governed identity, event, graph, merge, and proof layer inside SocioProphet.</p><p>This page is the readable overview of the subsystem. The canonical technical manual remains the <a href="/documentation/guide/entity-analytics-reference">Entity Analytics Reference</a>.</p><h2 id="_1-what-entity-analytics-is" tabindex="-1">1. What Entity Analytics is <a class="header-anchor" href="#_1-what-entity-analytics-is" aria-label="Permalink to &quot;1. What Entity Analytics is&quot;">​</a></h2><p>Entity Analytics exists because identity, events, graph structure, policy, and proof cannot be treated as unrelated layers.</p><p>The subsystem brings those pieces together so the platform can:</p><ul><li>model people and entities without collapsing everything into one ambient profile</li><li>preserve identity-relevant context across scopes</li><li>link or merge only under governance</li><li>emit proof-bearing outputs</li><li>keep reversal and auditability first-class</li></ul><p>This is not a generic CRM layer and not a conventional enterprise ER engine.</p><h2 id="_2-why-it-exists" tabindex="-1">2. Why it exists <a class="header-anchor" href="#_2-why-it-exists" aria-label="Permalink to &quot;2. Why it exists&quot;">​</a></h2><p>Traditional entity resolution optimizes for linkage accuracy under organizational control.</p><p>Entity Analytics optimizes for a stricter set of goals:</p><ul><li>preserve identity boundaries</li><li>permit governed linkage where justified</li><li>block unsafe merge and export paths</li><li>keep cross-context harm visible</li><li>attach evidence and policy to consequential transitions</li><li>preserve reversibility when later evidence or review changes the picture</li></ul><p>That is why the subsystem matters to the broader platform.</p><h2 id="_3-core-building-blocks" tabindex="-1">3. Core building blocks <a class="header-anchor" href="#_3-core-building-blocks" aria-label="Permalink to &quot;3. Core building blocks&quot;">​</a></h2><h3 id="typed-events" tabindex="-1">Typed events <a class="header-anchor" href="#typed-events" aria-label="Permalink to &quot;Typed events&quot;">​</a></h3><p>Every observation enters as a typed event rather than a generic row.</p><p>The system records:</p><ul><li>actor</li><li>scope</li><li>action</li><li>time</li><li>features</li><li>evidence</li><li>identity-relevant context</li></ul><p>This gives the platform a stronger basis for explanation and review.</p><h3 id="identity-prime-structure" tabindex="-1">Identity-prime structure <a class="header-anchor" href="#identity-prime-structure" aria-label="Permalink to &quot;Identity-prime structure&quot;">​</a></h3><p>Entity Analytics treats identity as structured composition rather than one undifferentiated blob.</p><p>The public claim is simple:</p><ul><li>different contexts can relate</li><li>different contexts can remain separate</li><li>different contexts can merge under policy</li><li>different contexts can remain blocked from one another</li></ul><p>That is the foundation of the identity-prime model.</p><h3 id="scopes" tabindex="-1">Scopes <a class="header-anchor" href="#scopes" aria-label="Permalink to &quot;Scopes&quot;">​</a></h3><p>Scope is first-class.</p><p>A scope can refer to:</p><ul><li>device</li><li>process</li><li>container</li><li>app</li><li>institution</li><li>jurisdiction</li><li>network class</li><li>other trust-relevant boundary</li></ul><p>Scope matters because a valid relation in one scope does not automatically become a valid merge or export in a wider one.</p><h3 id="governed-graph" tabindex="-1">Governed graph <a class="header-anchor" href="#governed-graph" aria-label="Permalink to &quot;Governed graph&quot;">​</a></h3><p>The system prefers a governed graph rather than a monolithic profile.</p><p>The graph can preserve:</p><ul><li>candidate links</li><li>asserted links</li><li>merges</li><li>blocked relations</li><li>revoked relations</li><li>unmerge lineage</li><li>proof artifacts</li></ul><p>This keeps the system honest about uncertainty, policy, and reversal.</p><h3 id="proof-artifacts" tabindex="-1">Proof artifacts <a class="header-anchor" href="#proof-artifacts" aria-label="Permalink to &quot;Proof artifacts&quot;">​</a></h3><p>Every high-consequence transition can emit a proof artifact carrying:</p><ul><li>claim</li><li>evidence</li><li>policy context</li><li>input hashes</li><li>witnesses</li><li>replay hooks</li><li>signatures</li><li>failure or counterexample traces where relevant</li></ul><p>That is what turns analytics into something reviewable.</p><h2 id="_4-what-makes-it-different" tabindex="-1">4. What makes it different <a class="header-anchor" href="#_4-what-makes-it-different" aria-label="Permalink to &quot;4. What makes it different&quot;">​</a></h2><p>Entity Analytics differs from ordinary enterprise identity systems in several ways.</p><h3 id="it-treats-identity-boundaries-as-real" tabindex="-1">It treats identity boundaries as real <a class="header-anchor" href="#it-treats-identity-boundaries-as-real" aria-label="Permalink to &quot;It treats identity boundaries as real&quot;">​</a></h3><p>The system does not assume that maximum merge is the right outcome.</p><h3 id="it-separates-evidence-from-admissibility" tabindex="-1">It separates evidence from admissibility <a class="header-anchor" href="#it-separates-evidence-from-admissibility" aria-label="Permalink to &quot;It separates evidence from admissibility&quot;">​</a></h3><p>A high-confidence link does not automatically become an allowed merge.</p><h3 id="it-separates-merge-from-export" tabindex="-1">It separates merge from export <a class="header-anchor" href="#it-separates-merge-from-export" aria-label="Permalink to &quot;It separates merge from export&quot;">​</a></h3><p>A valid merge still does not automatically become an allowed export.</p><h3 id="it-keeps-reversal-first-class" tabindex="-1">It keeps reversal first-class <a class="header-anchor" href="#it-keeps-reversal-first-class" aria-label="Permalink to &quot;It keeps reversal first-class&quot;">​</a></h3><p>Unmerge is not treated as embarrassment or system failure. It is part of the design.</p><h3 id="it-preserves-public-safe-proof" tabindex="-1">It preserves public-safe proof <a class="header-anchor" href="#it-preserves-public-safe-proof" aria-label="Permalink to &quot;It preserves public-safe proof&quot;">​</a></h3><p>The system can explain what happened without exposing restricted tactical internals.</p><h2 id="_5-public-safe-outputs" tabindex="-1">5. Public-safe outputs <a class="header-anchor" href="#_5-public-safe-outputs" aria-label="Permalink to &quot;5. Public-safe outputs&quot;">​</a></h2><p>Entity Analytics can produce useful outputs without exporting the whole person.</p><p>Public-safe outputs include things such as:</p><ul><li>bounded cohorts</li><li>coarse topic mixtures</li><li>time-windowed aggregates</li><li>suppression-aware segments</li><li>proof-carrying summaries</li></ul><p>Each output can be explained in terms of:</p><ul><li>what classes of inputs contributed</li><li>what contexts were excluded</li><li>what coarsening was applied</li><li>why the output remained policy-safe</li></ul><h2 id="_6-relationship-to-the-broader-platform" tabindex="-1">6. Relationship to the broader platform <a class="header-anchor" href="#_6-relationship-to-the-broader-platform" aria-label="Permalink to &quot;6. Relationship to the broader platform&quot;">​</a></h2><p>Entity Analytics is one of the core governed subsystems inside SocioProphet.</p><p>It connects directly to:</p><ul><li><a href="/documentation/guide/organizations-governance-and-institutional-safety">Organizations Governance and Institutional Safety</a></li><li><a href="/documentation/guide/governed-ai-and-cybernetics">Governed AI and Cybernetics</a></li><li><a href="/documentation/guide/agent-plane-and-operator-workflows">Agent Plane and Operator Workflows</a></li><li><a href="/documentation/guide/boundary-centric-cyber-hypergraph">Boundary-Centric Cyber Hypergraph</a></li><li><a href="/documentation/guide/authorized-cyberdefense-and-simulation">Authorized Cyberdefense and Simulation</a></li></ul><p>That is why the subsystem matters beyond analytics alone.</p><h2 id="_7-reading-paths" tabindex="-1">7. Reading paths <a class="header-anchor" href="#_7-reading-paths" aria-label="Permalink to &quot;7. Reading paths&quot;">​</a></h2><h3 id="read-the-full-technical-manual" tabindex="-1">Read the full technical manual <a class="header-anchor" href="#read-the-full-technical-manual" aria-label="Permalink to &quot;Read the full technical manual&quot;">​</a></h3><ul><li><a href="/documentation/guide/entity-analytics-reference">Entity Analytics Reference</a></li></ul><h3 id="read-the-worked-example" tabindex="-1">Read the worked example <a class="header-anchor" href="#read-the-worked-example" aria-label="Permalink to &quot;Read the worked example&quot;">​</a></h3><ul><li><a href="/documentation/guide/worked-example-michael-cross-context">Worked Example: Michael Cross-Context</a></li></ul><h3 id="read-the-narrower-companion-pages" tabindex="-1">Read the narrower companion pages <a class="header-anchor" href="#read-the-narrower-companion-pages" aria-label="Permalink to &quot;Read the narrower companion pages&quot;">​</a></h3><ul><li><a href="/documentation/guide/identity-prime-and-event-ir">Identity Prime and Event-IR</a></li><li><a href="/documentation/guide/entity-graph-and-safe-linkage">Entity Graph and Safe Linkage</a></li><li><a href="/documentation/guide/policy-constrained-merging-and-unmerge">Policy-Constrained Merging and Unmerge</a></li><li><a href="/documentation/guide/marketer-safe-outputs-and-segment-proofs">Marketer-Safe Outputs and Segment Proofs</a></li></ul><h2 id="_8-use-this-page" tabindex="-1">8. Use this page <a class="header-anchor" href="#_8-use-this-page" aria-label="Permalink to &quot;8. Use this page&quot;">​</a></h2><p>Use this page when the question is:</p><ul><li>What is Entity Analytics at a high level?</li><li>Why is it different from ordinary ER or CRM logic?</li><li>How do events, identity, scope, graph state, merge controls, and proof fit together?</li><li>Where do I go next for the full technical model?</li></ul>',71)])])}const m=a(n,[["render",l]]);export{u as __pageData,m as default};
